<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {listBases,generateStudyPlan,listStudyPlans,getStudyPlan,saveStudyPlan,replanStudyPlan,markStudyTask,listKnowledgeTopics,previewDocument,type StudyPlan} from '../api/client'
const bases=ref<any[]>([]),kb=ref(''),plans=ref<any[]>([]),plan=ref<StudyPlan|null>(null),topics=ref<any[]>([]),goal=ref(''),level=ref(''),deadline=ref(''),daily=ref(45),progressNote=ref(''),loading=ref(false),error=ref(''),notice=ref(''),preview=ref(''),previewTitle=ref('')
const val=(x:any,k:string)=>x[k.toUpperCase()]??x[k]
const chosen=computed(()=>bases.value.find(b=>val(b,'id')===kb.value))
async function refresh(){if(!kb.value)return;const [p,t]=await Promise.all([listStudyPlans(kb.value),listKnowledgeTopics(kb.value)]);plans.value=p.items||[];topics.value=t.items||[];if(plan.value?.id){plan.value=await getStudyPlan(plan.value.id);syncFormFromPlan()}}
async function selectKb(){plan.value=null;error.value='';try{await refresh()}catch(e:any){error.value=e.message}}
function syncFormFromPlan(){if(!plan.value)return;goal.value=plan.value.goal;level.value=plan.value.currentLevel;deadline.value=plan.value.deadline;daily.value=plan.value.dailyMinutes}
async function selectPlan(id:string){try{plan.value=await getStudyPlan(id);syncFormFromPlan()}catch(e:any){error.value=e.message}}
async function generate(){if(!kb.value)return;loading.value=true;error.value='';notice.value='';try{plan.value=await generateStudyPlan({knowledgeBaseId:kb.value,goal:goal.value,currentLevel:level.value,deadline:deadline.value,dailyMinutes:Number(daily.value)});await refresh();notice.value='计划已生成并保存'}catch(e:any){error.value=e.message}finally{loading.value=false}}
function move(index:number,delta:number){if(!plan.value)return;const next=index+delta;if(next<0||next>=plan.value.tasks.length)return;const copy=[...plan.value.tasks];[copy[index],copy[next]]=[copy[next],copy[index]];plan.value.tasks=copy}
function validEdit(){if(!goal.value.trim()){error.value='学习目标不能为空';return false}if(!deadline.value){error.value='请选择截止日期';return false}if(!Number.isInteger(Number(daily.value))||Number(daily.value)<5||Number(daily.value)>720){error.value='每日时间须为 5 至 720 分钟的整数';return false}if(plan.value?.tasks.some(t=>!t.title.trim()||!t.scheduledDate||!Number.isInteger(Number(t.estimatedMinutes))||Number(t.estimatedMinutes)<1||Number(t.estimatedMinutes)>1440)){error.value='请检查任务标题、安排日期和预计时长（1 至 1440 分钟）';return false}return true}
async function save(){if(!plan.value||!validEdit())return;loading.value=true;error.value='';notice.value='';try{plan.value=await saveStudyPlan({...plan.value,goal:goal.value.trim(),currentLevel:level.value.trim(),deadline:deadline.value,dailyMinutes:Number(daily.value)});await refresh();notice.value='计划修改已保存'}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function adjust(){if(!plan.value)return;loading.value=true;error.value='';try{plan.value=await replanStudyPlan(plan.value.id,progressNote.value);await refresh();notice.value='未完成任务已重新安排，完成记录已保留'}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function toggle(task:any){if(!plan.value)return;loading.value=true;try{plan.value=await markStudyTask(plan.value.id,task.id,!task.completed);await refresh()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function openSource(source:any){try{previewTitle.value=`${source.documentName||source.ORIGINAL_NAME||source.original_name} · ${source.location||'资料来源'}`;if(source.available===false){preview.value=`该来源片段已不在当前索引中，以下为计划保存时保留的资料摘录：\n\n${source.excerpt||''}`;return}const id=source.documentId||source.DOCUMENT_ID||source.document_id;const r=await previewDocument(id);preview.value=(r.text||source.excerpt||'').slice(0,9000)}catch(e:any){error.value=e.message}}
async function openTopic(topic:any){await openSource({documentId:topic.documentId,documentName:topic.documentName,location:topic.location,excerpt:topic.explanation,available:true})}
onMounted(async()=>{try{const r=await listBases();bases.value=r.items||[];if(bases.value.length){kb.value=String(val(bases.value[0],'id'));await selectKb()}}catch(e:any){error.value=e.message}})
</script>
<template>
  <section class="study-page">
    <div class="study-heading"><div><p class="eyebrow">STUDY PLANNER</p><h2>学习规划与知识探索</h2><p class="muted">依据当前知识库已索引资料生成计划，并查看可追溯的知识点。</p></div><label>知识库<select v-model="kb" @change="selectKb"><option v-for="b in bases" :key="val(b,'id')" :value="val(b,'id')">{{val(b,'name')}}</option></select></label></div>
    <p v-if="error" class="error">{{error}}</p><p v-if="notice" class="success">{{notice}}</p>
    <div v-if="!bases.length" class="card">请先创建知识库并导入资料。</div>
    <div v-else class="study-grid">
      <section class="card planner-form"><div class="section-title"><h3>{{plan?'编辑学习计划':'制定学习计划'}}</h3><span v-if="plan" class="tag">{{plan.progress.percent}}% 完成</span></div>
        <label>学习目标<input v-model="goal" maxlength="500" placeholder="例如：掌握 Java 集合框架" /></label><label>当前基础<input v-model="level" maxlength="1000" placeholder="描述已有基础或相关经验" /></label>
        <div class="form-row"><label>截止日期<input v-model="deadline" type="date" /></label><label>每日时间（分钟）<input v-model.number="daily" type="number" min="5" max="720" /></label></div>
        <button :disabled="loading||!goal.trim()||!deadline||Number(daily)<5||Number(daily)>720" @click="generate">{{loading?'处理中…':'生成新计划'}}</button>
        <button v-if="plan" class="secondary" :disabled="loading" @click="save">保存计划信息</button>
        <h3 class="subheading">已保存计划</h3><button v-for="p in plans" :key="val(p,'id')" class="plan-choice" :class="{chosen:val(p,'id')===plan?.id}" @click="selectPlan(val(p,'id'))">{{val(p,'goal')}} <small>{{val(p,'completedCount')??0}} / {{val(p,'taskCount')??0}} 项完成</small></button>
      </section>
      <section class="card task-panel"><template v-if="plan"><div class="section-title"><div><h3>{{plan.goal}}</h3><p class="muted">截止 {{plan.deadline}} · 每日 {{plan.dailyMinutes}} 分钟</p></div><strong>{{plan.progress.completed}} / {{plan.progress.total}}</strong></div><div class="progress-track"><span :style="{width:`${plan.progress.percent}%`}"></span></div>
        <ol class="task-list"><li v-for="(task,index) in plan.tasks" :key="task.id" class="task-item" :class="{done:task.completed}"><label class="task-check"><input type="checkbox" :checked="task.completed" @change="toggle(task)" /></label><div class="task-content"><input v-model="task.title" class="task-title" maxlength="300" aria-label="任务标题" /><textarea v-model="task.description" class="task-description" maxlength="3000" rows="3" aria-label="任务说明" placeholder="填写任务说明"></textarea><div class="task-edit-meta"><label>安排日期<input v-model="task.scheduledDate" type="date" /></label><label>预计时长（分钟）<input v-model.number="task.estimatedMinutes" type="number" min="1" max="1440" /></label></div><div class="task-meta"><button v-for="s in task.sources" :key="s.chunkId" class="source-link" @click="openSource(s)">{{s.documentName}} · {{s.location}}{{s.available?'':' · 原片段已删除或重建'}}</button><span v-if="!task.sources?.length" class="error">来源已不可用</span></div></div><div class="task-order"><button class="small" :disabled="index===0" @click="move(index,-1)">↑</button><button class="small" :disabled="index===plan.tasks.length-1" @click="move(index,1)">↓</button></div></li></ol>
        <label class="progress-note">学习进展<textarea v-model="progressNote" rows="2" placeholder="记录已掌握内容、遇到的困难或时间变化"></textarea></label><div class="actions"><button :disabled="loading" @click="save">保存任务编辑与排序</button><button class="secondary" :disabled="loading" @click="adjust">重新规划未完成任务</button></div>
      </template><div v-else class="empty-state">填写目标、基础、截止日期和每日时间，生成第一份学习计划。</div></section>
      <section class="card explorer"><div class="section-title"><div><h3>知识点探索</h3><p class="muted">从已索引资料标题和段落中整理，来源可打开。</p></div><span class="tag">{{topics.length}} 个条目</span></div><div v-if="!topics.length" class="empty-state">当前知识库暂无可识别的已索引知识点。</div><article v-for="topic in topics" :key="topic.chunkId+topic.title" class="topic-item"><button class="topic-title" @click="openTopic(topic)">{{topic.title}}</button><p>{{topic.explanation}}</p><button class="source-link" @click="openTopic(topic)">{{topic.documentName}} · {{topic.location}} ↗</button></article></section>
    </div>
    <div v-if="preview" class="preview-panel"><button class="close" @click="preview='';previewTitle=''">关闭</button><h3>{{previewTitle}}</h3><pre>{{preview}}</pre></div>
  </section>
</template>
